package com.mt8163.tools.ui;
import android.app.Activity;import android.os.Bundle;import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.FrameLayout;import android.widget.ListView;import com.mt8163.tools.MainApplication;import com.mt8163.tools.R;import com.mt8163.tools.core.ModuleContract;import com.mt8163.tools.core.ModuleRegistry;import com.mt8163.tools.core.PreferencesManager;import java.util.List;
public final class MainActivity extends Activity{
 private ModuleRegistry registry;private PreferencesManager prefs;private List<ModuleContract> modules;private SidebarAdapter adapter;private FrameLayout header,content;private View overlay;private int selected;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);MainApplication app=(MainApplication)getApplication();registry=app.getModuleRegistry();prefs=app.getPreferencesManager();modules=registry.getModules();ListView list=findViewById(R.id.sidebar_list);header=findViewById(R.id.header_container);content=findViewById(R.id.content_container);overlay=findViewById(R.id.disabled_overlay);adapter=new SidebarAdapter(this,modules);list.setAdapter(adapter);selected=modules.size()-1;list.setOnItemClickListener((p,v,pos,id)->showModule(pos));showModule(selected);}
 private void showModule(int pos){if(pos<0||pos>=modules.size())return;selected=pos;ModuleContract m=modules.get(pos);adapter.setSelectedPosition(pos);header.removeAllViews();ModuleHeaderView h=new ModuleHeaderView(this);h.bind(m,e->{registry.saveState(m,prefs);updateState();adapter.notifyDataSetChanged();});header.addView(h);content.removeAllViews();content.addView(LayoutInflater.from(this).inflate(m.getLayoutRes(),content,false));updateState();}
 private void updateState(){boolean on=modules.get(selected).isEnabled();setTreeEnabled(content,on);content.setAlpha(on?1f:0.32f);overlay.setVisibility(on?View.GONE:View.VISIBLE);}
 private void setTreeEnabled(View v,boolean on){v.setEnabled(on);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)setTreeEnabled(g.getChildAt(i),on);}}
}